#!/usr/bin/env python3
"""Fetch all message bodies with proper base64 padding."""
import json
import urllib.request
import base64

with open('/tmp/token.json') as f:
    token = json.load(f)['access_token']

GMAIL_URL = "http://localhost:9001"
MSG_IDS = [
    "351b9f16c5ef4109",
    "b69eebceeeb942e8",
    "e990d14e89c34879",
    "2cb22f6953d44f03",
    "1615370365874b2f",
    "502e1879eac44c3c",
    "e794c9d5c7a34ebb",
    "e50bb5398eae4362",
    "44d3d76b1d434d24",
    "52e288c9ec33465f",
]

def decode_body(data):
    """Decode base64url with proper padding."""
    if not data:
        return ""
    # Add padding
    missing = len(data) % 4
    if missing:
        data += '=' * (4 - missing)
    try:
        return base64.urlsafe_b64decode(data).decode('utf-8', 'replace')
    except Exception:
        return f"[decode error, raw len={len(data)}]"

def get_body(payload):
    """Recursively extract text body from payload."""
    mime = payload.get('mimeType', '')
    body_data = payload.get('body', {}).get('data', '')
    if body_data:
        return decode_body(body_data)
    if 'parts' in payload:
        # Prefer text/plain
        for p in payload['parts']:
            if p.get('mimeType') == 'text/plain':
                b = get_body(p)
                if b:
                    return b
        # Fall back to any part
        for p in payload['parts']:
            b = get_body(p)
            if b:
                return b
    return ""

for mid in MSG_IDS:
    req = urllib.request.Request(
        f"{GMAIL_URL}/gmail/v1/users/me/messages/{mid}?format=full",
        headers={"Authorization": f"Bearer {token}"}
    )
    with urllib.request.urlopen(req) as resp:
        m = json.loads(resp.read().decode())

    hdrs = {h['name'].lower(): h['value'] for h in m['payload']['headers']}
    body = get_body(m['payload'])

    print(f"{'='*60}")
    print(f"ID: {mid}")
    print(f"From: {hdrs.get('from','?')}")
    print(f"To: {hdrs.get('to','?')}")
    print(f"Subject: {hdrs.get('subject','?')}")
    print(f"Date: {hdrs.get('date','?')}")
    print(f"Labels: {m.get('labelIds',[])}")
    print(f"Snippet: {m.get('snippet','?')}")
    print(f"Body:\n{body[:2000]}")
    print()

